const p=$json.body;
if(!p || p.protocolVersion!==1 || !['openai','claude'].includes(p.provider) || !Array.isArray(p.messages) || !p.messages.length) throw new Error('Contrat Passerelle IA invalide.');
const last=p.messages[p.messages.length-1];
const files=p.messages.flatMap(m=>m.attachments||[]);
const names=files.map(f=>f.name+' ('+f.size+' octets)').join(', ')||'aucune';
const answer='TEST N8N RÉUSSI — aucune IA appelée.

Modèle demandé : '+p.provider.toUpperCase()+'
Dernier message : '+(last.text||'(pièces jointes seules)')+'
Historique reçu : '+p.messages.length+' messages.
Pièces jointes reçues : '+names+'

Quelle précision souhaitez-vous ajouter ? Répondez dans ce même chat et joignez un autre fichier pour tester la continuité.';
return [{json:{answer,conversationId:p.conversationId,requestId:p.requestId,provider:p.provider,mode:'echo'}}];
